/**
 * Build a chapter-by-chapter reading edition from one committed specification.
 *
 * The generated pages add only site metadata, source attribution, navigation,
 * local-link adaptation, and the heading shift needed when a chapter becomes
 * its own page. Check mode compares every generated byte with that projection.
 */
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  realpathSync,
  readFileSync,
  readdirSync,
  statSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "..",
);

function git(...args) {
  return execFileSync("git", args, { encoding: "utf8" }).trim();
}

function slugFor(number, title) {
  const slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  return `${String(number).padStart(2, "0")}-${slug}`;
}

function frontMatter(fields) {
  return [
    "---",
    ...Object.entries(fields).map(
      ([key, value]) => `${key}: ${JSON.stringify(value)}`,
    ),
    "---",
    "",
  ].join("\n");
}

function sourceAnchorFor(heading) {
  return heading
    .toLowerCase()
    .replace(/[`*_~]/g, "")
    .replace(/[^a-z0-9 _-]/g, "")
    .trim()
    .replace(/\s+/g, "-");
}

/** Shift source headings up one level without touching fenced examples. */
function promoteChapterHeadings(text) {
  let fenced = false;
  return text
    .split(/(?<=\n)/)
    .map((line) => {
      if (/^```/.test(line)) {
        fenced = !fenced;
        return line;
      }
      if (fenced) return line;
      const heading = /^(#{2,3}) ([^\n]+)(\n?)$/.exec(line);
      if (heading === null) return line;
      const anchor = sourceAnchorFor(heading[2]);
      return `<div id="${anchor}" class="nucleus-source-anchor"></div>\n\n${line.slice(1)}`;
    })
    .join("");
}

export function syncSpecification(config) {
  const outputDir = path.join(root, config.outputDirectory);
  const args = process.argv.slice(2);
  const checkOnly = args.includes("--check");
  const sourceArg = args.find((arg) => !arg.startsWith("--"));
  const requestedSourcePath =
    sourceArg === undefined ? undefined : path.resolve(sourceArg);

  if (requestedSourcePath === undefined) {
    console.error(`Pass the authoritative ${config.expectedSource} path.`);
    process.exit(2);
  }
  if (
    !existsSync(requestedSourcePath) ||
    !statSync(requestedSourcePath).isFile()
  ) {
    console.error(`Specification not found: ${requestedSourcePath}`);
    process.exit(2);
  }
  const sourcePath = realpathSync(requestedSourcePath);

  const sourceRoot = git(
    "-C",
    path.dirname(sourcePath),
    "rev-parse",
    "--show-toplevel",
  );
  const sourceRelativePath = path
    .relative(sourceRoot, sourcePath)
    .replaceAll(path.sep, "/");
  if (sourceRelativePath !== config.expectedSource) {
    console.error(
      `Expected ${config.expectedSource}, received ${sourceRelativePath}.`,
    );
    process.exit(2);
  }
  const sourceCommit = git(
    "-C",
    sourceRoot,
    "log",
    "-1",
    "--format=%H",
    "--",
    sourceRelativePath,
  );
  const source = readFileSync(sourcePath, "utf8");
  const committedSource = execFileSync(
    "git",
    ["-C", sourceRoot, "show", `${sourceCommit}:${sourceRelativePath}`],
    { encoding: "utf8", maxBuffer: 4 * 1024 * 1024 },
  );
  if (source !== committedSource) {
    console.error(
      "The source file differs from its latest committed revision. Commit it before publishing.",
    );
    process.exit(2);
  }

  const chapterMatches = [...source.matchAll(/^## (\d+)\. ([^\n]+)$/gm)];
  if (chapterMatches.length === 0) {
    console.error("No numbered chapters found.");
    process.exit(2);
  }
  chapterMatches.forEach((match, index) => {
    const expected = index + 1;
    if (Number(match[1]) !== expected) {
      throw new Error(`Expected chapter ${expected}, found ${match[1]}.`);
    }
  });

  const chapters = chapterMatches.map((match, index) => {
    const start = match.index;
    const end = chapterMatches[index + 1]?.index ?? source.length;
    return {
      number: Number(match[1]),
      title: match[2],
      slug: slugFor(Number(match[1]), match[2]),
      sourceText: source.slice(start, end),
    };
  });

  const anchorPages = new Map();
  for (const chapter of chapters) {
    for (const heading of chapter.sourceText.matchAll(/^#{2,3} ([^\n]+)$/gm)) {
      anchorPages.set(sourceAnchorFor(heading[1]), chapter.slug);
    }
  }

  function rewriteLinks(text, currentSlug) {
    let rewritten = text.replace(/\]\(#([a-z0-9_-]+)\)/g, (match, anchor) => {
      const destination = anchorPages.get(anchor);
      if (destination === undefined || destination === currentSlug)
        return match;
      return `](${destination}.md#${anchor})`;
    });
    for (const [from, to] of config.localLinks ?? []) {
      rewritten = rewritten.replaceAll(`](${from})`, `](${to})`);
    }
    return rewritten;
  }

  function chapterNavigation(index) {
    const links = [];
    if (index > 0) {
      const previous = chapters[index - 1];
      links.push(
        `[← ${previous.number}. ${previous.title}](${previous.slug}.md)`,
      );
    }
    links.push("[Contents](./)");
    if (index < chapters.length - 1) {
      const next = chapters[index + 1];
      links.push(`[${next.number}. ${next.title} →](${next.slug}.md)`);
    }
    return `${links.join(" · ")}\n\n`;
  }

  const sourceRepositoryUrl =
    config.sourceRepositoryUrl ?? "https://github.com/jhlagado/debug80";
  const sourceRepositoryLabel =
    config.sourceRepositoryLabel ?? "Debug80 repository";
  const sourceUrl = `${sourceRepositoryUrl}/blob/${sourceCommit}/${sourceRelativePath}`;
  const sourceMainUrl = `${sourceRepositoryUrl}/blob/main/${sourceRelativePath}`;
  const preamble = rewriteLinks(source.slice(0, chapterMatches[0].index));
  const titleEnd = preamble.indexOf("\n\n");
  if (titleEnd === -1)
    throw new Error("Expected a blank line after the specification title.");
  const sourceNotice = [
    "::: info Authoritative source",
    `This reading edition is generated from the [${config.sourceLabel} in the ${sourceRepositoryLabel}](${sourceMainUrl}) at revision [\`${sourceCommit.slice(0, 12)}\`](${sourceUrl}). The repository source is authoritative; this site adds page metadata and reading navigation, with headings and local links adapted to page boundaries. ${config.companion}`,
    ":::",
    "",
    "",
  ].join("\n");
  const indexBody =
    `${preamble.slice(0, titleEnd + 2)}${sourceNotice}${preamble.slice(titleEnd + 2)}`.replace(
      /\n+$/,
      "\n",
    );

  const expected = new Map();
  expected.set(
    "index.md",
    `${frontMatter({
      layout: "default",
      title: config.title,
      nav_order: config.navOrder,
      has_children: true,
      has_toc: false,
      standalone: true,
      isolated: true,
      pageClass: "nucleus-specification",
    })}<Mark class="book-plate" book="nucleus" size="52" />\n\n${indexBody}`,
  );

  chapters.forEach((chapter, index) => {
    const body = rewriteLinks(chapter.sourceText, chapter.slug);
    expected.set(
      `${chapter.slug}.md`,
      `${frontMatter({
        layout: "default",
        title: `${chapter.number}. ${chapter.title}`,
        parent: config.title,
        nav_order: chapter.number,
        pageClass: "nucleus-specification",
      })}${chapterNavigation(index)}${promoteChapterHeadings(body).replace(/\n+$/, "\n")}`,
    );
  });

  const expectedNames = [...expected.keys()].sort();
  let failed = false;
  if (checkOnly) {
    if (!existsSync(outputDir)) {
      console.error(`Generated book directory not found: ${outputDir}`);
      process.exit(1);
    }
    const actualNames = readdirSync(outputDir)
      .filter((name) => name.endsWith(".md"))
      .sort();
    if (actualNames.join("\n") !== expectedNames.join("\n")) {
      console.error(
        "Generated page list differs from the authoritative chapter list.",
      );
      failed = true;
    }
    for (const [name, contents] of expected) {
      const file = path.join(outputDir, name);
      if (!existsSync(file) || readFileSync(file, "utf8") !== contents) {
        console.error(
          `Generated page is stale or incomplete: ${path.relative(root, file)}`,
        );
        failed = true;
      }
    }
  } else {
    mkdirSync(outputDir, { recursive: true });
    for (const name of readdirSync(outputDir)) {
      if (name.endsWith(".md") && !expected.has(name))
        unlinkSync(path.join(outputDir, name));
    }
    for (const [name, contents] of expected)
      writeFileSync(path.join(outputDir, name), contents);
  }

  const digest = createHash("sha256").update(source).digest("hex");
  const action = checkOnly ? (failed ? "FAILED" : "verified") : "generated";
  console.log(
    `${action}: ${chapters.length} chapters, ${source.split("\n").length} lines, ${Buffer.byteLength(source)} bytes, sha256 ${digest}`,
  );
  console.log(`source: ${sourceCommit} ${sourceRelativePath}`);
  if (failed) process.exitCode = 1;
}
